#include <omp.h>
#include <cstddef>
#include <vector>

size_t findFirstEven(std::vector<int> const& x) {
    const std::size_t n = x.size();
    std::size_t first = n;  // If no even number exists, return x.size().

    #pragma omp parallel for default(none) shared(x, n) reduction(min:first)
    for (std::size_t i = 0; i < n; ++i) {
        if ((x[i] & 1) == 0) {
            first = i;
        }
    }

    return first;
}
